def agent_action(sandbox, agent_body, step_count):
    target = sandbox.get_target_speed()
    omega_measured = sandbox.get_wheel_angular_velocity()
    error = target - omega_measured
    current_speed = omega_measured

    # Determine gain based on current speed
    if current_speed < 0.3:
        K = 2.0  # Higher gain when stalled
    else:
        K = 1.0

    # Calculate torque required
    torque_required = error * K

    # Calculate torque limit based on current speed
    if current_speed > 3:
        torque_limit = 49.4
    else:
        torque_limit = 2.9 + 15.5 * current_speed

    # Apply deadzone logic
    TORQUE_DEADZONE = 2.6
    if abs(torque_required) < TORQUE_DEADZONE:
        if torque_required > 0:
            torque_required = TORQUE_DEADZONE + 0.1
        else:
            torque_required = -TORQUE_DEADZONE - 0.1

    # Clamp torque to actuator limits
    torque_clamped = max(min(torque_required, torque_limit), -torque_limit)

    # Apply the calculated torque
    sandbox.apply_motor_torque(torque_clamped)
